initJs:
function(container, apiUrl, tables) {
  let currentRecordId = null;

  // 時刻フォーマット関数
  function formatTime(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 日付フォーマット関数
  function formatDate(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleDateString('ja-JP');
  }

  // 分を時間表示に変換
  function formatMinutes(minutes) {
    if (!minutes) return '-';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return hours > 0 ? `${hours}時間${mins}分` : `${mins}分`;
  }

  // 作業項目テーブル再描画
  function renderWorkItems(workRecords) {
    const tbody = container.querySelector('#work-items-tbody');
    tbody.innerHTML = workRecords.map(record => `
      <tr data-id="${record.id}">
        <td>${record.プロジェクト名 || '-'}</td>
        <td>${record.作業場所 || '-'}</td>
        <td>${record.作業種別 || '-'}</td>
        <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${record.作業内容 || ''}">${record.作業内容 || '-'}</td>
        <td>
          <span style="font-size: 12px; padding: 2px 6px; border-radius: 3px; background: ${record.進捗状況 === '完了' ? '#d4edda' : record.進捗状況 === '作業中' ? '#fff3cd' : '#f8d7da'}; color: ${record.進捗状況 === '完了' ? '#155724' : record.進捗状況 === '作業中' ? '#856404' : '#721c24'};">
            ${record.進捗状況 || '-'}
          </span>
        </td>
        <td style="text-align: right; font-weight: 500;">${record.作業時間 || 0}</td>
      </tr>
    `).join('');
  }

  // 中断記録テーブル再描画
  function renderBreakRecords(breakRecords) {
    const tbody = container.querySelector('#break-records-tbody');
    if (!breakRecords || breakRecords.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; color: var(--text-muted); padding: 16px;">中断記録はありません</td></tr>';
      return;
    }

    tbody.innerHTML = breakRecords.map(record => `
      <tr data-id="${record.id}">
        <td>${formatTime(record.中断開始日時)}</td>
        <td>${formatTime(record.中断終了日時)}</td>
        <td style="text-align: right;">${record.中断時間 || 0}</td>
        <td>${record.中断理由区分 || '-'}</td>
        <td style="max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${record.中断理由詳細 || ''}">${record.中断理由詳細 || '-'}</td>
        <td>
          <span style="font-size: 12px; padding: 2px 6px; border-radius: 3px; background: ${record.影響度 === '軽微' ? '#d4edda' : record.影響度 === '中程度' ? '#fff3cd' : '#f8d7da'}; color: ${record.影響度 === '軽微' ? '#155724' : record.影響度 === '中程度' ? '#856404' : '#721c24'};">
            ${record.影響度 || '-'}
          </span>
        </td>
      </tr>
    `).join('');
  }

  // メイン画面更新
  async function updateDisplay(recordId) {
    try {
      // 作業記録取得
      const workRecords = await window.aivicApi.list(1);
      const currentRecord = workRecords.find(r => r.id === recordId);

      if (!currentRecord) {
        alert('作業記録が見つかりません');
        return;
      }

      currentRecordId = recordId;

      // 作業員情報取得
      const users = await window.aivicApi.list(0);
      const worker = users.find(u => u.id === currentRecord.作業員ID);

      // 中断記録取得
      const breakRecords = await window.aivicApi.list(2);
      const relatedBreaks = breakRecords.filter(b => b.作業記録ID === recordId);

      // 異常値検出ログ取得
      const anomalyLogs = await window.aivicApi.list(4);
      const hasAnomaly = anomalyLogs.some(log => 
        log.検出対象レコードID === recordId && log.確認状況 === '未確認'
      );

      // 基本情報表示
      container.querySelector('#worker-name').textContent = worker ? worker.氏名 : '-';
      container.querySelector('#work-date').textContent = formatDate(currentRecord.作業日);

      // 承認状態
      const statusEl = container.querySelector('#approval-status');
      statusEl.textContent = currentRecord.承認状態 || '未承認';
      statusEl.style.background = currentRecord.承認状態 === '承認済み' ? '#d4edda' : 
                                  currentRecord.承認状態 === '差し戻し' ? '#f8d7da' : '#f0f0f0';
      statusEl.style.color = currentRecord.承認状態 === '承認済み' ? '#155724' : 
                            currentRecord.承認状態 === '差し戻し' ? '#721c24' : '#666';

      // 異常値警告
      const warningEl = container.querySelector('#anomaly-warning');
      if (hasAnomaly) {
        warningEl.classList.remove('hidden');
      } else {
        warningEl.classList.add('hidden');
      }

      // 時間情報
      container.querySelector('#start-time').textContent = formatTime(currentRecord.作業開始時刻);
      container.querySelector('#end-time').textContent = formatTime(currentRecord.作業終了時刻);
      container.querySelector('#work-hours').textContent = formatMinutes(currentRecord.作業時間);

      // 中断時間合計
      const totalBreakTime = relatedBreaks.reduce((sum, b) => sum + (b.中断時間 || 0), 0);
      container.querySelector('#break-hours').textContent = formatMinutes(totalBreakTime);

      // 合計工数
      const totalHours = (currentRecord.作業時間 || 0) + totalBreakTime;
      container.querySelector('#total-hours').textContent = formatMinutes(totalHours);

      // 作業内容・備考
      container.querySelector('#work-detail').textContent = currentRecord.作業内容 || '-';
      container.querySelector('#work-memo').textContent = currentRecord.備考 || '-';

      // テーブル更新
      renderWorkItems([currentRecord]);
      renderBreakRecords(relatedBreaks);

    } catch (error) {
      console.error('データ取得エラー:', error);
    }
  }

  // 修正ボタン
  container.querySelector('#btn-modify').addEventListener('click', () => {
    if (currentRecordId) {
      window.showScreen("scr-1778907343735");
    } else {
      alert('修正対象の記録が選択されていません');
    }
  });

  // 承認ボタン
  container.querySelector('#btn-approve').addEventListener('click', async () => {
    if (!currentRecordId) {
      alert('承認対象の記録が選択されていません');
      return;
    }

    if (!confirm('この工数記録を承認しますか？')) return;

    try {
      const updated = await window.aivicApi.update(1, currentRecordId, {
        承認状態: '承認済み',
        承認日時: new Date().toISOString(),
        承認者ID: 'current-user-id' // 実際の実装では現在のユーザーIDを使用
      });

      if (updated) {
        alert('承認が完了しました');
        updateDisplay(currentRecordId);
      }
    } catch (error) {
      console.error('承認エラー:', error);
      alert('承認処理に失敗しました');
    }
  });

  // 初期表示（最初の作業記録を表示）
  if (tables[1] && tables[1].records && tables[1].records.length > 0) {
    updateDisplay(tables[1].records[0].id);
  }
}
